using System;
using System.Data;
using InformationWebObject;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// Truy cập CMS_LandingPage qua stored procedure.
    /// </summary>
    public static class LandingPageService
    {
        public static DataTable Search(string keyword)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("CMS_LandingPage_SearchCMS", "@KeyWord", keyword ?? "");
        }

        public static DataTable GetById(int landingPageId)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("CMS_LandingPage_GetByIDCMS", "@LandingPageID", landingPageId);
        }

        public static DataTable GetBySlug(string slug)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("CMS_LandingPage_GetBySlug", "@Slug", slug ?? "");
        }

        public static int Save(
            int landingPageId,
            string pageName,
            string slug,
            string title,
            string metaDescription,
            bool isActive,
            string createdUser,
            string updatedUser)
        {
            INFO_Information info = new INFO_Information();
            object pageIdParam = landingPageId > 0 ? (object)landingPageId : DBNull.Value;

            DataTable dt = info.GetDataTable(
                "CMS_LandingPage_SaveCMS",
                "@LandingPageID", pageIdParam,
                "@PageName", pageName ?? "",
                "@Slug", slug ?? "",
                "@Title", title ?? "",
                "@MetaDescription", string.IsNullOrEmpty(metaDescription) ? (object)DBNull.Value : metaDescription,
                "@IsActive", isActive ? 1 : 0,
                "@CreatedUser", string.IsNullOrEmpty(createdUser) ? (object)DBNull.Value : createdUser,
                "@UpdatedUser", string.IsNullOrEmpty(updatedUser) ? (object)DBNull.Value : updatedUser
            );

            if (landingPageId > 0)
                return landingPageId;

            if (dt != null && dt.Rows.Count > 0 && dt.Columns.Contains("LandingPageID"))
                return Convert.ToInt32(dt.Rows[0]["LandingPageID"]);

            return 0;
        }

        public static bool Delete(int landingPageId)
        {
            INFO_Information info = new INFO_Information();
            info.GetDataTable("CMS_LandingPage_DeleteCMS", "@LandingPageID", landingPageId);
            return true;
        }

        public static int Copy(int landingPageId, string createdUser)
        {
            INFO_Information info = new INFO_Information();
            DataTable dt = info.GetDataTable(
                "CMS_LandingPage_CopyCMS",
                "@LandingPageID", landingPageId,
                "@CreatedUser", string.IsNullOrEmpty(createdUser) ? (object)DBNull.Value : createdUser
            );

            if (dt != null && dt.Rows.Count > 0 && dt.Columns.Contains("LandingPageID"))
                return Convert.ToInt32(dt.Rows[0]["LandingPageID"]);

            return 0;
        }
    }
}

using System;
using System.Data;
using InformationWebObject;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// Truy cập CMS_LandingBlock qua stored procedure.
    /// </summary>
    public static class LandingBlockService
    {
        public static DataTable ListByPage(int landingPageId, bool includeInactive)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable(
                "CMS_LandingBlock_ListByPage",
                "@LandingPageID", landingPageId,
                "@IncludeInactive", includeInactive ? 1 : 0
            );
        }

        public static DataTable GetById(int blockId)
        {
            INFO_Information info = new INFO_Information();
            return info.GetDataTable("CMS_LandingBlock_GetByID", "@BlockID", blockId);
        }

        public static int Save(
            int blockId,
            int landingPageId,
            string blockType,
            string title,
            string content,
            string imageUrl,
            string buttonText,
            string buttonLink,
            int sortOrder,
            bool isActive,
            string configJson)
        {
            INFO_Information info = new INFO_Information();
            object blockIdParam = blockId > 0 ? (object)blockId : DBNull.Value;

            DataTable dt = info.GetDataTable(
                "CMS_LandingBlock_SaveCMS",
                "@BlockID", blockIdParam,
                "@LandingPageID", landingPageId,
                "@BlockType", blockType ?? "",
                "@Title", string.IsNullOrEmpty(title) ? (object)DBNull.Value : title,
                "@Content", string.IsNullOrEmpty(content) ? (object)DBNull.Value : content,
                "@ImageUrl", string.IsNullOrEmpty(imageUrl) ? (object)DBNull.Value : imageUrl,
                "@ButtonText", string.IsNullOrEmpty(buttonText) ? (object)DBNull.Value : buttonText,
                "@ButtonLink", string.IsNullOrEmpty(buttonLink) ? (object)DBNull.Value : buttonLink,
                "@SortOrder", sortOrder,
                "@IsActive", isActive ? 1 : 0,
                "@ConfigJson", string.IsNullOrEmpty(configJson) ? (object)DBNull.Value : configJson
            );

            if (blockId > 0)
                return blockId;

            if (dt != null && dt.Rows.Count > 0 && dt.Columns.Contains("BlockID"))
                return Convert.ToInt32(dt.Rows[0]["BlockID"]);

            return 0;
        }

        public static bool Delete(int blockId)
        {
            INFO_Information info = new INFO_Information();
            info.GetDataTable("CMS_LandingBlock_DeleteCMS", "@BlockID", blockId);
            return true;
        }

        public static bool UpdateSortOrder(int landingPageId, string blockIdsCsv)
        {
            INFO_Information info = new INFO_Information();
            info.GetDataTable(
                "CMS_LandingBlock_UpdateSortOrder",
                "@LandingPageID", landingPageId,
                "@BlockIDs", blockIdsCsv ?? ""
            );
            return true;
        }

        public static bool ToggleActive(int blockId, bool isActive)
        {
            INFO_Information info = new INFO_Information();
            info.GetDataTable(
                "CMS_LandingBlock_ToggleActive",
                "@BlockID", blockId,
                "@IsActive", isActive ? 1 : 0
            );
            return true;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Text;
using System.Web;
using Newtonsoft.Json.Linq;

namespace InformationCMS.Controls.LandingPage
{
    /// <summary>
    /// Render HTML block cho frontend landing page.
    /// </summary>
    public static class LandingBlockRenderer
    {
        public static string RenderPage(DataTable blocks)
        {
            if (blocks == null || blocks.Rows.Count < 1)
                return "<div class=\"container py-5\"><p class=\"text-muted\">Nội dung đang được cập nhật.</p></div>";

            StringBuilder sb = new StringBuilder();
            foreach (DataRow row in blocks.Rows)
            {
                sb.Append(RenderBlock(row));
            }
            return sb.ToString();
        }

        public static string RenderBlock(DataRow row)
        {
            string blockType = Convert.ToString(row["BlockType"]).ToLowerInvariant();
            string title = row["Title"] == DBNull.Value ? "" : Convert.ToString(row["Title"]);
            string content = row["Content"] == DBNull.Value ? "" : Convert.ToString(row["Content"]);
            string imageUrl = row["ImageUrl"] == DBNull.Value ? "" : Convert.ToString(row["ImageUrl"]);
            string buttonText = row["ButtonText"] == DBNull.Value ? "" : Convert.ToString(row["ButtonText"]);
            string buttonLink = row["ButtonLink"] == DBNull.Value ? "" : Convert.ToString(row["ButtonLink"]);
            string configJson = row["ConfigJson"] == DBNull.Value ? "" : Convert.ToString(row["ConfigJson"]);

            switch (blockType)
            {
                case "hero":
                    return RenderHero(title, content, imageUrl, buttonText, buttonLink, configJson);
                case "html":
                    return RenderHtml(content);
                case "image_content":
                    return RenderImageContent(title, content, imageUrl, configJson);
                case "gallery":
                    return RenderGallery(title, configJson);
                case "video":
                    return RenderVideo(title, content, configJson);
                case "faq":
                    return RenderFaq(title, configJson);
                case "form":
                    return RenderForm(title, configJson);
                case "cta":
                    return RenderCta(title, content, buttonText, buttonLink);
                case "custom_html":
                    return RenderCustomHtml(content);
                default:
                    return RenderHtml(content);
            }
        }

        private static string RenderHero(string title, string content, string imageUrl, string buttonText, string buttonLink, string configJson)
        {
            string subtitle = GetConfigString(configJson, "subtitle");
            string bgStyle = string.IsNullOrEmpty(imageUrl)
                ? "background: linear-gradient(135deg, #0f477d 0%, #1a6bb5 100%);"
                : string.Format("background: linear-gradient(rgba(0,0,0,.45), rgba(0,0,0,.45)), url('{0}') center/cover no-repeat;", HttpUtility.HtmlAttributeEncode(imageUrl));

            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-hero text-white py-5\" style=\"");
            sb.Append(bgStyle);
            sb.Append("\"><div class=\"container py-4 text-center\">");
            if (!string.IsNullOrEmpty(title))
                sb.AppendFormat("<h1 class=\"display-5 fw-bold mb-3\">{0}</h1>", HttpUtility.HtmlEncode(title));
            if (!string.IsNullOrEmpty(subtitle))
                sb.AppendFormat("<p class=\"lead mb-3\">{0}</p>", HttpUtility.HtmlEncode(subtitle));
            if (!string.IsNullOrEmpty(content))
                sb.AppendFormat("<div class=\"mb-4\">{0}</div>", content);
            if (!string.IsNullOrEmpty(buttonText) && !string.IsNullOrEmpty(buttonLink))
                sb.AppendFormat("<a href=\"{0}\" class=\"btn btn-light btn-lg\">{1}</a>",
                    HttpUtility.HtmlAttributeEncode(buttonLink), HttpUtility.HtmlEncode(buttonText));
            sb.Append("</div></section>");
            return sb.ToString();
        }

        private static string RenderHtml(string content)
        {
            if (string.IsNullOrEmpty(content))
                return "";
            return string.Format("<section class=\"lp-block lp-html py-4\"><div class=\"container\">{0}</div></section>", content);
        }

        private static string RenderImageContent(string title, string content, string imageUrl, string configJson)
        {
            string imagePosition = GetConfigString(configJson, "imagePosition");
            if (string.IsNullOrEmpty(imagePosition))
                imagePosition = "left";

            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-image-content py-5\"><div class=\"container\"><div class=\"row align-items-center g-4\">");

            string imageCol = string.Format("<div class=\"col-md-6\"><img src=\"{0}\" alt=\"{1}\" class=\"img-fluid rounded shadow-sm\" /></div>",
                HttpUtility.HtmlAttributeEncode(imageUrl), HttpUtility.HtmlAttributeEncode(title));
            string textCol = new StringBuilder()
                .Append("<div class=\"col-md-6\">")
                .Append(string.IsNullOrEmpty(title) ? "" : string.Format("<h2 class=\"fw-bold mb-3\">{0}</h2>", HttpUtility.HtmlEncode(title)))
                .Append(string.IsNullOrEmpty(content) ? "" : string.Format("<div>{0}</div>", content))
                .Append("</div>").ToString();

            if (imagePosition == "right")
            {
                sb.Append(textCol);
                sb.Append(imageCol);
            }
            else
            {
                sb.Append(imageCol);
                sb.Append(textCol);
            }

            sb.Append("</div></div></section>");
            return sb.ToString();
        }

        private static string RenderGallery(string title, string configJson)
        {
            List<string> images = GetConfigStringList(configJson, "images");
            if (images.Count < 1)
                return "";

            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-gallery py-5 bg-light\"><div class=\"container\">");
            if (!string.IsNullOrEmpty(title))
                sb.AppendFormat("<h2 class=\"fw-bold text-center mb-4\">{0}</h2>", HttpUtility.HtmlEncode(title));
            sb.Append("<div class=\"row g-3\">");
            foreach (string img in images)
            {
                sb.AppendFormat("<div class=\"col-6 col-md-4 col-lg-3\"><img src=\"{0}\" class=\"img-fluid rounded shadow-sm w-100\" alt=\"\" /></div>",
                    HttpUtility.HtmlAttributeEncode(img));
            }
            sb.Append("</div></div></section>");
            return sb.ToString();
        }

        private static string RenderVideo(string title, string content, string configJson)
        {
            string videoUrl = GetConfigString(configJson, "videoUrl");
            if (string.IsNullOrEmpty(videoUrl))
                videoUrl = content;

            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-video py-5\"><div class=\"container\">");
            if (!string.IsNullOrEmpty(title))
                sb.AppendFormat("<h2 class=\"fw-bold text-center mb-4\">{0}</h2>", HttpUtility.HtmlEncode(title));
            sb.Append("<div class=\"ratio ratio-16x9 rounded overflow-hidden shadow-sm\">");
            sb.AppendFormat("<iframe src=\"{0}\" title=\"{1}\" allowfullscreen></iframe>",
                HttpUtility.HtmlAttributeEncode(videoUrl), HttpUtility.HtmlAttributeEncode(title));
            sb.Append("</div></div></section>");
            return sb.ToString();
        }

        private static string RenderFaq(string title, string configJson)
        {
            JArray items = GetConfigArray(configJson, "items");
            if (items == null || items.Count < 1)
                return "";

            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-faq py-5\"><div class=\"container\">");
            if (!string.IsNullOrEmpty(title))
                sb.AppendFormat("<h2 class=\"fw-bold text-center mb-4\">{0}</h2>", HttpUtility.HtmlEncode(title));
            sb.Append("<div class=\"accordion\" id=\"lpFaqAccordion\">");

            for (int i = 0; i < items.Count; i++)
            {
                JToken item = items[i];
                string question = item["question"] != null ? item["question"].ToString() : "";
                string answer = item["answer"] != null ? item["answer"].ToString() : "";
                string collapseId = string.Format("faqCollapse{0}", i);

                sb.Append("<div class=\"accordion-item\">");
                sb.AppendFormat("<h2 class=\"accordion-header\"><button class=\"accordion-button{0}\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#{1}\">{2}</button></h2>",
                    i == 0 ? "" : " collapsed", collapseId, HttpUtility.HtmlEncode(question));
                sb.AppendFormat("<div id=\"{0}\" class=\"accordion-collapse collapse{1}\" data-bs-parent=\"#lpFaqAccordion\"><div class=\"accordion-body\">{2}</div></div>",
                    collapseId, i == 0 ? " show" : "", answer);
                sb.Append("</div>");
            }

            sb.Append("</div></div></section>");
            return sb.ToString();
        }

        private static string RenderForm(string title, string configJson)
        {
            string submitText = GetConfigString(configJson, "submitText");
            if (string.IsNullOrEmpty(submitText))
                submitText = "Gửi đăng ký";

            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-form py-5 bg-light\"><div class=\"container\"><div class=\"row justify-content-center\"><div class=\"col-md-8 col-lg-6\">");
            sb.Append("<div class=\"card shadow-sm border-0\"><div class=\"card-body p-4\">");
            if (!string.IsNullOrEmpty(title))
                sb.AppendFormat("<h3 class=\"fw-bold mb-3 text-center\">{0}</h3>", HttpUtility.HtmlEncode(title));
            sb.Append("<form class=\"lp-register-form\" onsubmit=\"return false;\">");
            sb.Append("<div class=\"mb-3\"><label class=\"form-label\">Họ tên</label><input type=\"text\" class=\"form-control\" name=\"fullName\" required /></div>");
            sb.Append("<div class=\"mb-3\"><label class=\"form-label\">Email</label><input type=\"email\" class=\"form-control\" name=\"email\" required /></div>");
            sb.Append("<div class=\"mb-3\"><label class=\"form-label\">Số điện thoại</label><input type=\"tel\" class=\"form-control\" name=\"phone\" /></div>");
            sb.AppendFormat("<button type=\"submit\" class=\"btn btn-primary w-100\">{0}</button>", HttpUtility.HtmlEncode(submitText));
            sb.Append("</form></div></div></div></div></div></section>");
            return sb.ToString();
        }

        private static string RenderCta(string title, string content, string buttonText, string buttonLink)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("<section class=\"lp-block lp-cta py-5 text-center\" style=\"background:#0f477d;color:#fff;\"><div class=\"container\">");
            if (!string.IsNullOrEmpty(title))
                sb.AppendFormat("<h2 class=\"fw-bold mb-3\">{0}</h2>", HttpUtility.HtmlEncode(title));
            if (!string.IsNullOrEmpty(content))
                sb.AppendFormat("<p class=\"lead mb-4\">{0}</p>", content);
            if (!string.IsNullOrEmpty(buttonText) && !string.IsNullOrEmpty(buttonLink))
                sb.AppendFormat("<a href=\"{0}\" class=\"btn btn-light btn-lg\">{1}</a>",
                    HttpUtility.HtmlAttributeEncode(buttonLink), HttpUtility.HtmlEncode(buttonText));
            sb.Append("</div></section>");
            return sb.ToString();
        }

        private static string RenderCustomHtml(string content)
        {
            if (string.IsNullOrEmpty(content))
                return "";
            return string.Format("<section class=\"lp-block lp-custom-html\">{0}</section>", content);
        }

        private static string GetConfigString(string configJson, string key)
        {
            if (string.IsNullOrEmpty(configJson))
                return "";
            try
            {
                JObject obj = JObject.Parse(configJson);
                if (obj[key] == null)
                    return "";
                return obj[key].ToString();
            }
            catch
            {
                return "";
            }
        }

        private static List<string> GetConfigStringList(string configJson, string key)
        {
            List<string> list = new List<string>();
            if (string.IsNullOrEmpty(configJson))
                return list;
            try
            {
                JObject obj = JObject.Parse(configJson);
                JArray arr = obj[key] as JArray;
                if (arr == null)
                    return list;
                for (int i = 0; i < arr.Count; i++)
                {
                    if (arr[i] != null)
                        list.Add(arr[i].ToString());
                }
            }
            catch
            {
            }
            return list;
        }

        private static JArray GetConfigArray(string configJson, string key)
        {
            if (string.IsNullOrEmpty(configJson))
                return null;
            try
            {
                JObject obj = JObject.Parse(configJson);
                return obj[key] as JArray;
            }
            catch
            {
                return null;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Web;
using System.Web.Script.Serialization;
using System.Web.SessionState;
using DCore;
using InformationCMS.Controls.LandingPage;
using Newtonsoft.Json.Linq;

namespace InformationCMS
{
    /// <summary>
    /// Ajax API cho CMS Landing Page blocks.
    /// action: list | get | save | delete | sort | toggle
    /// </summary>
    public class LandingBlockHandler : IHttpHandler, IRequiresSessionState
    {
        private const string PermissionAddEdit = "CMS_LandingPage_AddEdit";

        public bool IsReusable { get { return false; } }

        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json; charset=utf-8";
            context.Response.ContentEncoding = System.Text.Encoding.UTF8;

            if (!CheckPermission(context))
            {
                WriteJson(context, new { success = false, message = "Bạn không có quyền thực hiện thao tác này." });
                return;
            }

            string action = (context.Request["action"] ?? "").ToLowerInvariant();

            try
            {
                switch (action)
                {
                    case "list":
                        HandleList(context);
                        break;
                    case "get":
                        HandleGet(context);
                        break;
                    case "save":
                        HandleSave(context);
                        break;
                    case "delete":
                        HandleDelete(context);
                        break;
                    case "sort":
                        HandleSort(context);
                        break;
                    case "toggle":
                        HandleToggle(context);
                        break;
                    default:
                        WriteJson(context, new { success = false, message = "Action không hợp lệ." });
                        break;
                }
            }
            catch (Exception ex)
            {
                WriteJson(context, new { success = false, message = ex.Message });
            }
        }

        private static bool CheckPermission(HttpContext context)
        {
            SessionUser user = context.Session[Globals.USER] as SessionUser;
            if (user == null)
                return false;
            return user.IsPermission(PermissionAddEdit);
        }

        private static void HandleList(HttpContext context)
        {
            int landingPageId = GetInt(context.Request["landingPageId"]);
            if (landingPageId < 1)
            {
                WriteJson(context, new { success = false, message = "Thiếu landingPageId." });
                return;
            }

            DataTable dt = LandingBlockService.ListByPage(landingPageId, true);
            WriteJson(context, new { success = true, data = DataTableToList(dt) });
        }

        private static void HandleGet(HttpContext context)
        {
            int blockId = GetInt(context.Request["blockId"]);
            if (blockId < 1)
            {
                WriteJson(context, new { success = false, message = "Thiếu blockId." });
                return;
            }

            DataTable dt = LandingBlockService.GetById(blockId);
            if (dt == null || dt.Rows.Count < 1)
            {
                WriteJson(context, new { success = false, message = "Không tìm thấy block." });
                return;
            }

            WriteJson(context, new { success = true, data = RowToDict(dt.Rows[0]) });
        }

        private static void HandleSave(HttpContext context)
        {
            string body = context.Request.Form["data"];
            if (string.IsNullOrEmpty(body))
                body = ReadRequestBody(context);

            if (string.IsNullOrEmpty(body))
            {
                WriteJson(context, new { success = false, message = "Thiếu dữ liệu." });
                return;
            }

            JObject json = JObject.Parse(body);
            int blockId = json["BlockID"] != null ? Convert.ToInt32(json["BlockID"]) : 0;
            int landingPageId = json["LandingPageID"] != null ? Convert.ToInt32(json["LandingPageID"]) : 0;

            if (landingPageId < 1)
            {
                WriteJson(context, new { success = false, message = "Thiếu LandingPageID." });
                return;
            }

            string blockType = json["BlockType"] != null ? json["BlockType"].ToString() : "";
            string title = json["Title"] != null ? json["Title"].ToString() : "";
            string content = json["Content"] != null ? json["Content"].ToString() : "";
            string imageUrl = json["ImageUrl"] != null ? json["ImageUrl"].ToString() : "";
            string buttonText = json["ButtonText"] != null ? json["ButtonText"].ToString() : "";
            string buttonLink = json["ButtonLink"] != null ? json["ButtonLink"].ToString() : "";
            int sortOrder = json["SortOrder"] != null ? Convert.ToInt32(json["SortOrder"]) : 0;
            bool isActive = json["IsActive"] == null || Convert.ToBoolean(json["IsActive"]);
            string configJson = json["ConfigJson"] != null ? json["ConfigJson"].ToString() : "";

            int savedId = LandingBlockService.Save(
                blockId,
                landingPageId,
                blockType,
                title,
                content,
                imageUrl,
                buttonText,
                buttonLink,
                sortOrder,
                isActive,
                configJson
            );

            if (savedId < 1)
            {
                WriteJson(context, new { success = false, message = "Lưu block thất bại." });
                return;
            }

            DataTable dt = LandingBlockService.GetById(savedId);
            WriteJson(context, new { success = true, data = RowToDict(dt.Rows[0]) });
        }

        private static void HandleDelete(HttpContext context)
        {
            int blockId = GetInt(context.Request["blockId"]);
            if (blockId < 1)
            {
                WriteJson(context, new { success = false, message = "Thiếu blockId." });
                return;
            }

            LandingBlockService.Delete(blockId);
            WriteJson(context, new { success = true });
        }

        private static void HandleSort(HttpContext context)
        {
            int landingPageId = GetInt(context.Request["landingPageId"]);
            string blockIds = context.Request["blockIds"] ?? "";

            if (landingPageId < 1 || string.IsNullOrEmpty(blockIds))
            {
                WriteJson(context, new { success = false, message = "Thiếu tham số sort." });
                return;
            }

            LandingBlockService.UpdateSortOrder(landingPageId, blockIds);
            WriteJson(context, new { success = true });
        }

        private static void HandleToggle(HttpContext context)
        {
            int blockId = GetInt(context.Request["blockId"]);
            bool isActive = (context.Request["isActive"] ?? "1") == "1";

            if (blockId < 1)
            {
                WriteJson(context, new { success = false, message = "Thiếu blockId." });
                return;
            }

            LandingBlockService.ToggleActive(blockId, isActive);
            WriteJson(context, new { success = true });
        }

        private static int GetInt(string value)
        {
            int n = 0;
            if (!string.IsNullOrEmpty(value))
                int.TryParse(value, out n);
            return n;
        }

        private static string ReadRequestBody(HttpContext context)
        {
            using (System.IO.StreamReader reader = new System.IO.StreamReader(context.Request.InputStream))
            {
                return reader.ReadToEnd();
            }
        }

        private static List<Dictionary<string, object>> DataTableToList(DataTable dt)
        {
            List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
            if (dt == null)
                return list;
            foreach (DataRow row in dt.Rows)
                list.Add(RowToDict(row));
            return list;
        }

        private static Dictionary<string, object> RowToDict(DataRow row)
        {
            Dictionary<string, object> dict = new Dictionary<string, object>();
            foreach (DataColumn col in row.Table.Columns)
            {
                object val = row[col];
                if (val == DBNull.Value)
                    dict[col.ColumnName] = null;
                else if (col.DataType == typeof(bool))
                    dict[col.ColumnName] = Convert.ToBoolean(val);
                else
                    dict[col.ColumnName] = val;
            }
            return dict;
        }

