                    WriteJson(context, new { error = "Cannot create upload folder." });
                    return;
                }
            }

            string baseUrl = GetLogicalImageBaseUrl();
            if (string.IsNullOrWhiteSpace(baseUrl))
                baseUrl = GetBaseUrlFromRequest(context);

            List<string> uploadedUrls = new List<string>();

            for (int i = 0; i < context.Request.Files.Count; i++)
            {
                HttpPostedFile file = context.Request.Files[i];
                if (file == null || file.ContentLength == 0) continue;

                if (file.ContentLength > MaxFileSizeBytes)
                {
                    WriteJson(context, new { error = "File too large. Max 10MB." });
                    return;
                }

                string ext = Path.GetExtension(file.FileName) ?? "";
                if (string.IsNullOrEmpty(ext) || Array.IndexOf(AllowedExtensions, ext.ToLowerInvariant()) < 0)
                {
                    WriteJson(context, new { error = "Invalid file type. Allowed: jpg, png, gif, webp." });
                    return;
                }

                string fileName = string.Format("{0:yyyyMMdd}-{0:HHmmss}-{1}{2}",
                    DateTime.Now, new Random().Next(1000, 9999), ext.ToLowerInvariant());
                string fullPath = Path.Combine(basePath, fileName);

                try
                {
                    file.SaveAs(fullPath);
                    string relativePath = UseCustomPhysicalPath(context)
                        ? "/uploads/landingpage/" + fileName
                        : VirtualPathUtility.ToAbsolute("~/uploads/landingpage/" + fileName);
                    uploadedUrls.Add(baseUrl.TrimEnd('/') + relativePath);
                }
                catch (Exception ex)
                {
                    WriteJson(context, new { error = "Save failed: " + ex.Message });
                    return;
                }
            }

            if (uploadedUrls.Count == 0)
            {
                WriteJson(context, new { error = "No valid file uploaded." });
                return;
            }

            WriteJson(context, new { data = uploadedUrls });
        }

        private static bool UseCustomPhysicalPath(HttpContext context)
        {
            return !string.IsNullOrWhiteSpace(DCore.ConfigManager.GetConfig("LandingPage_Physical_ImagePath"));
        }

        private static string GetPhysicalImagePath(HttpContext context)
        {
            string path = DCore.ConfigManager.GetConfig("LandingPage_Physical_ImagePath");
            if (!string.IsNullOrWhiteSpace(path))
            {
                path = path.Trim().TrimEnd('\\', '/');
                if (!Path.IsPathRooted(path))
                    path = context.Server.MapPath("~/" + path.TrimStart('/', '\\'));
                return path + "\\";
            }
            return context.Server.MapPath("~/uploads/landingpage/");
        }

        private static string GetLogicalImageBaseUrl()
        {
            string logical = DCore.ConfigManager.GetConfig("WebsiteRoot");
            if (!string.IsNullOrWhiteSpace(logical))
                return logical.Trim().TrimEnd('/');
            string root = CMSGlobal.WebsiteRoot;
            return string.IsNullOrWhiteSpace(root) ? null : root.Trim();
        }

        private static string GetBaseUrlFromRequest(HttpContext context)
        {
            HttpRequest req = context.Request;
            int port = req.Url.Port;
            if ((port == 80 && req.Url.Scheme == "http") || (port == 443 && req.Url.Scheme == "https"))
                port = 0;
            return port > 0
                ? string.Format("{0}://{1}:{2}", req.Url.Scheme, req.Url.Host, port)
                : string.Format("{0}://{1}", req.Url.Scheme, req.Url.Host);
        }

        private static void WriteJson(HttpContext context, object obj)
        {
            context.Response.Write(Newtonsoft.Json.JsonConvert.SerializeObject(obj));
        }
    }
