{
    JToken token = json[key];
    if (token == null || token.Type == JTokenType.Null)
        return "";
    return token.ToString();
}

private static int GetJsonInt(JObject json, string key, int defaultValue)
{
    JToken token = json[key];
    if (token == null || token.Type == JTokenType.Null)
        return defaultValue;

    int n = 0;
    if (int.TryParse(token.ToString(), out n))
        return n;
    return defaultValue;
}

private static bool GetJsonBool(JObject json, string key, bool defaultValue)
{
    JToken token = json[key];
    if (token == null || token.Type == JTokenType.Null)
        return defaultValue;

    if (token.Type == JTokenType.Boolean)
        return token.Value<bool>();

    string s = token.ToString().ToLowerInvariant();
    if (s == "true" || s == "1")
        return true;
    if (s == "false" || s == "0")
        return false;
    return defaultValue;
}

